begin;
set local search_path=public,extensions,pg_temp;select no_plan();
update public.app_settings set generation_paused=false,claims_paused=true,limits=limits||'{"enabledGenerationModes":["education"],"globalByteLimitConfigured":true}';
update public.usage_accounts set byte_limit=1000000000 where scope='global';
insert into auth.users(id,email,raw_user_meta_data) values('c1900000-0000-4000-8000-000000000001','w19-sql@example.invalid','{"display_name":"Cancellation fixture"}'),('c1900000-0000-4000-8000-000000000002','w19-other@example.invalid','{"display_name":"Other"}');
insert into public.usage_accounts(scope,owner_id,byte_limit,output_limit) values('user','c1900000-0000-4000-8000-000000000001',400000000,3);
insert into public.projects(id,owner_id,title,mode,draft_input) values('c1910000-0000-4000-8000-000000000001','c1900000-0000-4000-8000-000000000001','Turbines','education','{"topic":"How turbines work","audience":"beginner","intendedUse":"personal-learning","sources":[]}');
select set_config('request.jwt.claims','{"sub":"c1900000-0000-4000-8000-000000000001","role":"authenticated"}',true);
create temporary table cancellation_fixture(job uuid,assignment jsonb);
create function pg_temp.new_cancel_job(k text) returns uuid language sql as $$select (public.enqueue_generation('c1910000-0000-4000-8000-000000000001',k,'{"draftVersion":1,"preferences":{"targetSeconds":60,"orientation":"landscape","voiceProfileId":"Kore"},"acknowledgments":{"sourceRights":true,"externalAiProcessing":true,"policyVersion":"v1"}}')->>'jobId')::uuid$$;
insert into cancellation_fixture(job) values(pg_temp.new_cancel_job('waiting'));
select ok(not has_function_privilege('anon','public.cancel_generation(uuid)','execute'),'Anonymous cancellation denied');
select set_config('request.jwt.claims','{"sub":"c1900000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.cancel_generation((select job from cancellation_fixture))$$,'42501',null::text,'Foreign cancellation hidden');
select set_config('request.jwt.claims','{"sub":"c1900000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is(public.cancel_generation((select job from cancellation_fixture))->>'status','cancelled','Unassigned job stops immediately');
select is((select active_ms from public.jobs where id=(select job from cancellation_fixture)),0::bigint,'Unstarted cancellation has a valid zero active clock');
select is((select state from public.usage_reservations where job_id=(select job from cancellation_fixture)),'released','Unassigned reservation released');
select is(public.cancel_generation((select job from cancellation_fixture))->>'status','cancelled','Cancellation replay is safe');
select is((select count(*)::integer from public.usage_ledger where owner_id='c1900000-0000-4000-8000-000000000001' and reason='terminal worker lease'),1,'One terminal release for repeated cancellation');
select throws_ok($$select public.retry_generation((select job from cancellation_fixture),'retry-cancelled')$$,'P1801',null::text,'Cancelled cannot be resumed with Retry');
update cancellation_fixture set job=pg_temp.new_cancel_job('quota');
update public.jobs set status='waiting_quota',retry_at=now()+interval '1 hour' where id=(select job from cancellation_fixture);
select is(public.cancel_generation((select job from cancellation_fixture))->>'status','cancelled','Provider wait can be cancelled without contacting a provider');
insert into public.workers(id,label,enabled,protocol_version,capabilities) select ('c1920000-0000-4000-8000-00000000000'||n)::uuid,'Cancellation fixture',true,1,'{"modes":["education"],"orientations":["landscape","portrait"],"schemaVersions":[1],"compositionVersion":"v1"}' from generate_series(1,2)n;
insert into public.worker_credentials(worker_id,token_hash,expires_at) select ('c1920000-0000-4000-8000-00000000000'||n)::uuid,repeat(case when n=1 then 'c' else 'd' end,64),now()+interval '1 hour' from generate_series(1,2)n;
create function pg_temp.claim_cancel_job() returns jsonb language sql as $$select public.worker_control(repeat('c',64),1,'claim','{"instanceId":"c1920000-0000-4000-8000-000000000011","capabilities":{"modes":["education"],"orientations":["landscape","portrait"],"schemaVersions":[1],"compositionVersion":"v1"}}')$$;
create function pg_temp.execute_cancel_fixture(op jsonb) returns jsonb language sql as $$select public.worker_execute(repeat('c',64),1,jsonb_build_object('instanceId','c1920000-0000-4000-8000-000000000011','jobId',assignment->>'jobId','leaseToken',assignment->>'leaseToken','health','{}'::jsonb,'operation',op)) from cancellation_fixture$$;
update cancellation_fixture set job=pg_temp.new_cancel_job('running');update public.app_settings set claims_paused=false;
update cancellation_fixture set assignment=pg_temp.claim_cancel_job();
select is((select status from public.jobs where id=(select job from cancellation_fixture)),'running','Fixture has a real fenced assignment');
select pg_temp.execute_cancel_fixture(jsonb_build_object('type','attempt','nonce',gen_random_uuid(),'operationKey','in-flight','provider','Gemini','modelId','fixture','requestHash',repeat('a',64)));
select pg_temp.execute_cancel_fixture(jsonb_build_object('type','allocate','key','partial','kind','audio','bytes',1000,'checksum',repeat('a',64)));
select is(public.cancel_generation((select job from cancellation_fixture))->>'status','cancel_requested','Live assignment enters stopping');
select throws_ok($$select pg_temp.new_cancel_job('cannot-start-during-stop')$$,'P1401',null::text,'Stopping retains the one-active-generation boundary');
create temporary table cancel_sequence as select event_sequence from public.jobs where id=(select job from cancellation_fixture);
select is(public.cancel_generation((select job from cancellation_fixture))->>'status','cancel_requested','Repeated live cancellation remains stopping');
select is((select event_sequence from public.jobs where id=(select job from cancellation_fixture)),(select event_sequence from cancel_sequence),'No duplicate cancellation event');
select is((select state from public.usage_reservations where job_id=(select job from cancellation_fixture)),'reserved','Capacity held until acknowledgment');
select throws_ok($$select pg_temp.execute_cancel_fixture('{"type":"complete","key":"late"}')$$,'P1503',null::text,'Cancel flag prevents late publication before argument processing');
select is((select public.worker_control(repeat('c',64),1,'heartbeat',jsonb_build_object('instanceId','c1920000-0000-4000-8000-000000000011','health','{}'::jsonb,'assignment',jsonb_build_object('jobId',job,'leaseToken',assignment->>'leaseToken')))->>'cancelRequested' from cancellation_fixture),'true','Worker heartbeat observes cancellation');
select is((select public.worker_control(repeat('c',64),1,'release',jsonb_build_object('instanceId','c1920000-0000-4000-8000-000000000011','jobId',job,'leaseToken',assignment->>'leaseToken','reason','stopping'))->>'status' from cancellation_fixture),'cancelled','Stopped worker acknowledges through release');
select is((select state from public.usage_reservations where job_id=(select job from cancellation_fixture)),'released','Acknowledgment releases reservation');
select is((select status from public.provider_attempts where job_id=(select job from cancellation_fixture)),'outcome_unknown','In-flight provider usage stays conservatively unknown');
select is((select provider_attempt_count from public.jobs where id=(select job from cancellation_fixture)),1,'Cancellation never refunds provider attempts');
select is((select used_bytes from public.usage_accounts where owner_id='c1900000-0000-4000-8000-000000000001'),1000::bigint,'Allocated bytes remain charged until physical cleanup');
select throws_ok($$select pg_temp.execute_cancel_fixture('{"type":"complete","key":"late"}')$$,'P1503',null::text,'Acknowledged old lease cannot publish');
select is((select count(*)::integer from public.exports where revision_id in(select revision_id from public.jobs where id=(select job from cancellation_fixture))),0,'No cancelled result export exists');
update cancellation_fixture set job=pg_temp.new_cancel_job('disconnected'),assignment=null;update cancellation_fixture set assignment=pg_temp.claim_cancel_job();
select public.cancel_generation((select job from cancellation_fixture));
update public.jobs set lease_expires_at=clock_timestamp()-interval '1 second',last_heartbeat_at=clock_timestamp()-interval '10 seconds' where id=(select job from cancellation_fixture);
update public.worker_slots set lease_expires_at=clock_timestamp()-interval '1 second' where job_id=(select job from cancellation_fixture);
select is(public.cancel_generation((select job from cancellation_fixture))->>'status','cancelled','Expired authority reconciles without worker return');
select is((select job_id from public.worker_slots where slot_name='processing'),null::uuid,'Expired cancellation frees processing slot');
update cancellation_fixture set job=pg_temp.new_cancel_job('idle-reconcile'),assignment=null;update cancellation_fixture set assignment=pg_temp.claim_cancel_job();
select public.cancel_generation((select job from cancellation_fixture));
update public.jobs set lease_expires_at=clock_timestamp()-interval '1 second',last_heartbeat_at=clock_timestamp()-interval '10 seconds' where id=(select job from cancellation_fixture);
update public.worker_slots set lease_expires_at=clock_timestamp()-interval '1 second' where job_id=(select job from cancellation_fixture);
update public.app_settings set claims_paused=true;
select public.worker_control(repeat('d',64),1,'heartbeat','{"instanceId":"c1920000-0000-4000-8000-000000000012","health":{}}');
select is((select status from public.jobs where id=(select job from cancellation_fixture)),'cancelled','Unrelated idle heartbeat reconciles expired cancellation even with claims paused');
select is((select reserved_outputs from public.usage_accounts where owner_id='c1900000-0000-4000-8000-000000000001'),0,'All synthetic reservations released once');
select * from finish();rollback;
